using BrudvikWhiteHilt.Helpers;
using Jotunn.Configs;
using UnityEngine;

namespace BrudvikWhiteHilt.Items.Foraging.SeaBuckthorn;

/// <summary>
/// Sea buckthorn, a thorny silver shrub crowded with orange berries that takes root in ash and wind, in the Ashlands.
/// Model: generated by AssetSource/Tools/make_forage_models.py; the berries hide when picked. Asksvin sometimes carry
/// them in their crops.
/// </summary>
public class SeaBuckthorn : ForageableBase
{
    /// <summary>
    /// Prefab name of the sea buckthorn berries item.
    /// </summary>
    public const string PrefabName = "WhiteHiltSeaBuckthorn";

    /// <inheritdoc/>
    public override string BaseName => PrefabName;

    /// <inheritdoc/>
    protected override string FullName => "Sea Buckthorn";

    /// <inheritdoc/>
    protected override string Description => "Sour orange berries packed tight along thorny twigs. They keep the body going through the hardest winter.";

    /// <inheritdoc/>
    protected override string CopyItemFrom => "Raspberry";

    /// <inheritdoc/>
    protected override string CopyPickableFrom => "RaspberryBush";

    /// <inheritdoc/>
    protected override VegetationConfig Vegetation => new()
    {
        Biome = Heightmap.Biome.AshLands,
        // Groups per zone where the ground suits it; the generator keeps trying spots until they are placed.
        Min = 1,
        Max = 1,
        ForcePlacement = true,
        GroupSizeMin = 1,
        GroupSizeMax = 3,
        GroupRadius = 5f,
        MinAltitude = 1f,
        MaxTilt = 25f,
        ScaleMin = 0.85f,
        ScaleMax = 1.15f,
        BlockCheck = true
    };

    /// <inheritdoc/>
    public override bool Enabled => true;

    /// <inheritdoc/>
    protected override string ExtraDropFrom => null;

    /// <inheritdoc/>
    protected override string CreatureDropFrom => "Asksvin";

    /// <inheritdoc/>
    protected override float CreatureDropChance => 0.15f;

    /// <inheritdoc/>
    protected override void ApplyVisual(GameObject visualRoot)
    {
        // Raspberries turn the orange of sea buckthorn.
        VisualHelper.RecolorHue(visualRoot, 0.85f, 1f, 0.08f, 1.15f, 1.15f);
    }

    /// <inheritdoc/>
    protected override void ApplyPickableVisual(GameObject pickablePrefab, Pickable pickable)
    {
        ReplaceBushMesh(pickablePrefab, pickable, "seabuckthorn", 1.3f);
    }
}
